const schedulingFeedback=import('/request-feedback.js');
function openStudentAppointment(studentId){return import('/appointment-form.js').then(m=>m.mountAppointmentForm(studentId))}
if(location.pathname.replace(/\/+$/,'')==='/agendamento'){
 if(!document.documentElement.hasAttribute('data-site-rendered'))document.title='Central de agendamento — Luta pela Comunidade';
 if(!document.documentElement.hasAttribute('data-site-rendered')||!document.querySelector('main form'))document.querySelector('main').innerHTML=`<section class="section registration-intro"><p class="eyebrow">ACOMPANHAMENTO DO ALUNO</p><h1>Central de agendamento</h1><p><a class="button" href="/portal/#schedule-area">Entrar e ver horários disponíveis</a></p><p>Use o email habilitado no cadastro. Na área protegida você encontra o nome do aluno, os documentos e os horários publicados pelos profissionais.</p><p class="lead">Atendimento com a assistência social e a psicóloga, exclusivo para alunos aprovados no projeto.</p></section><section class="section registration-layout"><div><div class="form-status">A consulta de ID está disponível. Informe o código recebido da coordenação para verificar seu cadastro. A secretaria deverá conferir o responsável; o atendimento só estará confirmado após o WhatsApp da secretaria ao aluno ou responsável.</div><form id="student-scheduling"><fieldset><legend>01 · Identificação do aluno</legend><div class="form-grid"><label>ID do aluno<input id="scheduling-student-id" name="studentId" required maxlength="64" autocomplete="off" spellcheck="false" autocapitalize="characters" aria-describedby="student-id-help student-id-confidentiality"><small id="student-id-help">Digite o ID fornecido pela coordenação após a aprovação da inscrição.</small></label></div><div class="privacy-note" id="student-id-confidentiality"><h3>Seu ID é confidencial</h3><p>O ID é de uso exclusivo do aluno e de seu responsável legal. Não é permitida sua divulgação a terceiros, em redes sociais, grupos ou publicações. Compartilhe-o apenas com a equipe autorizada do projeto, quando necessário para o atendimento.</p><p>O ID aprovado permite solicitar um horário. A secretaria confere a identidade do responsável antes de confirmar o atendimento. Se o ID tiver sido divulgado, comunique a coordenação.</p></div></fieldset><button class="button" type="submit">Verificar acesso</button><div id="scheduling-access-status" role="status" tabindex="-1" hidden></div><p><a class="text-link" href="/inscricao/">Ainda não tenho ID — quero me inscrever</a></p></form></div><aside class="registration-aside"><p class="eyebrow">PASSO A PASSO</p><h2>Cuidado em cada etapa.</h2><ol><li>Inscrição do aluno pelo responsável.</li><li>Conferência dos documentos e aprovação.</li><li>Recebimento confidencial do ID.</li><li>Confirmação de acesso pelo responsável.</li><li>Escolha de uma vaga presencial ou online, ou envio de preferência.</li><li>Confirmação pela secretaria, por WhatsApp ao aluno ou responsável.</li></ol><p>Seu histórico e seus documentos não são exibidos nesta página.</p><a href="/inscricao/" class="text-link">Realizar inscrição</a></aside></section>`;
 const form=document.querySelector('#student-scheduling'),input=document.querySelector('#scheduling-student-id'),status=document.querySelector('#scheduling-access-status');
 input.addEventListener('input',()=>{input.setCustomValidity('');status.hidden=true;status.textContent=''});
 // The server checks the private registry. ID lookup is not authentication or a reservation.
 const submit=form.querySelector('button[type=submit]'),initialSubmitLabel=submit.textContent;
 form.addEventListener('submit',async e=>{e.preventDefault();input.setCustomValidity(input.value.trim()?'':'Digite o ID fornecido pela coordenação.');if(!form.reportValidity())return;const studentId=input.value.trim();submit.disabled=true;submit.textContent='Consultando cadastro…';status.hidden=true;status.replaceChildren();try{const response=await (await schedulingFeedback).requestResponse('/api/student-access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId})});const data=await response.json();status.textContent=data.message||'Não foi possível consultar o cadastro. Tente novamente.';if(response.ok&&data.verified===true){await openStudentAppointment(studentId);return}if(response.ok&&data.training===true){window.dispatchEvent(new Event('lpc:training-access'));return}}catch(error){status.textContent=error.message||'Não foi possível conectar à consulta. Tente novamente.'}finally{submit.disabled=false;submit.textContent=initialSubmitLabel;status.className='form-status';status.hidden=false;status.focus()}});
}



